base = 0x16d;
while (base < 0x17c) {
    action = 0;
    mapped = base;
    do {
        if (key == mapped) {
            return provider->is_active(player, action);
        }
        ++action;
        ++mapped;
    } while (action < 5);
    base += 5;
    ++player;
}
